import type { Metadata } from "next";
import Link from "next/link";
import {
  ChevronRight,
  Search,
  Zap,
  AlertCircle,
  ArrowRight,
  CheckCircle2,
  HelpCircle,
  GitFork,
  Clock,
  ShieldCheck,
  Compass,
} from "lucide-react";

const CANONICAL = "https://www.trayago.in/split-journey";

// ── SEO Metadata ───────────────────────────────────────────────────────────────

export const metadata: Metadata = {
  title: "AI Split Train Journey Planner — Alternative Route Discovery | Trayago",
  description:
    "Discover how split train ticketing works on Indian Railways. Trayago's AI Split Journey engine evaluates intermediate railway junction combinations when direct trains are waitlisted.",
  keywords:
    "split train journey, split journey Indian railways, connecting train routes, train ticket alternative, split ticketing India, train intermediate junction, waitlist alternative route, AI train route planner",
  alternates: { canonical: CANONICAL },
  robots: { index: true, follow: true },
  openGraph: {
    type: "website",
    title: "AI Split Train Journey Planner — Alternative Route Discovery | Trayago",
    description:
      "When direct trains are full, Trayago evaluates intermediate junction combinations to uncover available seats across connecting segments.",
    url: CANONICAL,
    siteName: "Trayago",
  },
  twitter: {
    card: "summary_large_image",
    title: "AI Split Train Journey Planner — Trayago",
    description:
      "Discover connecting train route combinations across Indian Railways when through tickets are waitlisted.",
  },
};

// ── FAQ Data (Visible Content + JSON-LD) ──────────────────────────────────────

const SPLIT_FAQS: { q: string; a: string }[] = [
  {
    q: "What is a split train journey?",
    a: "A split journey divides a longer train trip into two or more distinct segments connected via an intermediate railway junction. Instead of travelling end-to-end on a single direct train, you travel on one train to a transfer station and switch to a connecting train to reach your final destination.",
  },
  {
    q: "Why do split journeys have seat availability when direct trains are waitlisted?",
    a: "Direct long-distance trains usually exhaust their end-to-end quota quickly because travellers book the full corridor. However, intermediate segments and regional trains often have unallocated seats or separate booking quotas. By splitting the journey at a major junction, travellers can tap into available inventory on individual legs.",
  },
  {
    q: "Does a split journey guarantee a confirmed seat?",
    a: "No. Trayago surfaces feasible connecting combinations and the seat availability reported by reservation systems at the time of your search. Railway quotas and booking status fluctuate in real time, and ticket confirmation is determined solely by Indian Railways at the time of purchase.",
  },
  {
    q: "What are the primary risks of booking a split journey?",
    a: "The primary operational risk is a missed connection. If your first train suffers an unexpected delay and arrives after your second train departs, the second train will not wait. To minimize this risk, Trayago encourages selecting generous layover buffer times (at least 1.5 to 3 hours) and checking live running status before travelling.",
  },
  {
    q: "Do I need separate tickets for each leg of a split journey?",
    a: "Yes. Each leg is operated as an independent train service with its own PNR, coach allocation, quota, and fare. You must purchase a separate ticket for each train leg on official booking channels like IRCTC.",
  },
  {
    q: "Is a split journey cheaper than a direct train ticket?",
    a: "Not necessarily. In many cases, booking two separate tickets incurs two base fare calculations and reservation fees, which can make the total cost slightly higher than a single direct ticket. The main benefit of a split journey is route availability when through trains are sold out, not price savings.",
  },
  {
    q: "Can I book railway tickets directly on Trayago?",
    a: "No. Trayago is an independent journey intelligence and route planning platform. We do not issue railway tickets, process ticket booking payments, or act as an IRCTC booking agent. Once you find a suitable route, tickets must be booked through official portals such as IRCTC.",
  },
  {
    q: "Is Trayago affiliated with IRCTC or Indian Railways?",
    a: "No. Trayago is an independent platform and has no affiliation with, endorsement from, or official relationship with IRCTC or the Ministry of Railways, Government of India.",
  },
];

// ── Structured Data Schemas ────────────────────────────────────────────────────

const breadcrumbJsonLd = {
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  itemListElement: [
    { "@type": "ListItem", position: 1, name: "Home", item: "https://www.trayago.in" },
    { "@type": "ListItem", position: 2, name: "AI Split Journey", item: CANONICAL },
  ],
};

const webPageJsonLd = {
  "@context": "https://schema.org",
  "@type": "WebPage",
  name: "AI Split Train Journey Planner — Alternative Route Discovery",
  url: CANONICAL,
  description:
    "Learn how split train ticketing works on Indian Railways. Trayago's AI Split Journey engine evaluates intermediate railway junction combinations when direct trains are waitlisted.",
  isPartOf: {
    "@type": "WebSite",
    name: "Trayago",
    url: "https://www.trayago.in",
  },
};

const faqPageJsonLd = {
  "@context": "https://schema.org",
  "@type": "FAQPage",
  mainEntity: SPLIT_FAQS.map((faq) => ({
    "@type": "Question",
    name: faq.q,
    acceptedAnswer: {
      "@type": "Answer",
      text: faq.a,
    },
  })),
};

export default function SplitJourneyPage() {
  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbJsonLd) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(webPageJsonLd) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(faqPageJsonLd) }}
      />

      <div className="min-h-screen bg-background text-foreground">
        {/* Breadcrumb Navigation */}
        <nav
          aria-label="Breadcrumb"
          className="border-b border-border/40 bg-card/30 px-4 py-3 sm:px-6 lg:px-8"
        >
          <div className="mx-auto flex max-w-5xl items-center gap-2 text-xs text-muted-foreground">
            <Link href="/" className="hover:text-foreground transition-colors">
              Home
            </Link>
            <ChevronRight className="h-3.5 w-3.5" />
            <span className="text-foreground font-medium">Split Journey</span>
          </div>
        </nav>

        {/* Hero Section */}
        <section className="relative overflow-hidden border-b border-border/40 px-4 py-12 sm:px-6 sm:py-16 lg:px-8">
          <div className="mx-auto max-w-5xl">
            <div className="inline-flex items-center gap-2 rounded-full border border-primary/20 bg-primary/10 px-3 py-1 text-xs font-semibold text-primary mb-6">
              <GitFork className="h-3.5 w-3.5" />
              Route Discovery Technology
            </div>
            <h1 className="text-3xl font-extrabold tracking-tight sm:text-5xl lg:text-6xl text-foreground">
              AI Split Journey Planner
            </h1>
            <p className="mt-4 max-w-3xl text-base sm:text-lg text-muted-foreground leading-relaxed">
              When direct trains between major Indian cities are fully booked or heavily waitlisted,
              Trayago evaluates connecting segments via key railway junction hubs to uncover alternative travel options.
            </p>

            {/* Quick Action CTAs */}
            <div className="mt-8 flex flex-wrap items-center gap-3">
              <Link
                href="/"
                className="inline-flex items-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground shadow-sm hover:bg-primary/90 transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
              >
                <Search className="h-4 w-4" />
                Search Train Routes
              </Link>
              <Link
                href="/ai-waitlist-rescue"
                className="inline-flex items-center gap-2 rounded-xl border border-border bg-card/60 px-5 py-3 text-sm font-semibold text-foreground hover:bg-card transition-all"
              >
                <Zap className="h-4 w-4 text-amber-500" />
                AI Waitlist Rescue
              </Link>
              <Link
                href="/live"
                className="inline-flex items-center gap-2 rounded-xl border border-border bg-card/60 px-5 py-3 text-sm font-semibold text-foreground hover:bg-card transition-all"
              >
                <Compass className="h-4 w-4 text-blue-500" />
                Live Status
              </Link>
            </div>
          </div>
        </section>

        {/* How Split Journeys Work */}
        <section className="border-b border-border/40 px-4 py-12 sm:px-6 lg:px-8">
          <div className="mx-auto max-w-5xl">
            <h2 className="text-2xl font-bold tracking-tight text-foreground sm:text-3xl mb-4">
              How a Split Journey Works
            </h2>
            <p className="text-sm sm:text-base text-muted-foreground mb-8 max-w-3xl leading-relaxed">
              Indian Railways operates with segmented quotas and high passenger concentration between end terminals.
              A split journey connects two independent trains through an intermediate station.
            </p>

            <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
              <div className="rounded-2xl border border-border/60 bg-card/50 p-5">
                <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary/10 text-primary font-bold text-sm mb-4">
                  1
                </div>
                <h3 className="font-semibold text-foreground text-sm mb-1.5">Direct Route Full</h3>
                <p className="text-xs text-muted-foreground leading-relaxed">
                  End-to-end seats on high-demand express trains enter Waitlist (WL) or Regret status weeks in advance.
                </p>
              </div>

              <div className="rounded-2xl border border-border/60 bg-card/50 p-5">
                <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary/10 text-primary font-bold text-sm mb-4">
                  2
                </div>
                <h3 className="font-semibold text-foreground text-sm mb-1.5">Junction Hub Matching</h3>
                <p className="text-xs text-muted-foreground leading-relaxed">
                  The algorithm identifies major railway junctions (e.g. Bhopal, Kanpur, Nagpur, Vijayawada) that intersect both origins and destinations.
                </p>
              </div>

              <div className="rounded-2xl border border-border/60 bg-card/50 p-5">
                <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary/10 text-primary font-bold text-sm mb-4">
                  3
                </div>
                <h3 className="font-semibold text-foreground text-sm mb-1.5">Buffer Evaluation</h3>
                <p className="text-xs text-muted-foreground leading-relaxed">
                  Transfer windows are calculated to provide sufficient time between arrival of Leg 1 and departure of Leg 2.
                </p>
              </div>

              <div className="rounded-2xl border border-border/60 bg-card/50 p-5">
                <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary/10 text-primary font-bold text-sm mb-4">
                  4
                </div>
                <h3 className="font-semibold text-foreground text-sm mb-1.5">Official Booking</h3>
                <p className="text-xs text-muted-foreground leading-relaxed">
                  You review the proposed schedule and complete the separate ticket bookings through official channels such as IRCTC.
                </p>
              </div>
            </div>
          </div>
        </section>

        {/* Practical Passenger Guidance & Important Risk Disclosure */}
        <section className="border-b border-border/40 px-4 py-12 sm:px-6 lg:px-8 bg-card/20">
          <div className="mx-auto max-w-5xl">
            <div className="rounded-2xl border border-amber-500/20 bg-amber-500/5 p-6 sm:p-8">
              <div className="flex items-start gap-4">
                <AlertCircle className="h-6 w-6 text-amber-500 shrink-0 mt-0.5" />
                <div>
                  <h3 className="text-base font-bold text-foreground mb-2">
                    Essential Passenger Guidelines Before You Book
                  </h3>
                  <ul className="space-y-2.5 text-xs sm:text-sm text-muted-foreground leading-relaxed">
                    <li className="flex items-start gap-2">
                      <Clock className="h-4 w-4 text-amber-500 shrink-0 mt-0.5" />
                      <span>
                        <strong>Allow generous transfer time:</strong> Always choose connections with at least 1.5 to 3 hours between legs. Trains in India can face unexpected delays, and the connecting train cannot wait for delayed incoming services.
                      </span>
                    </li>
                    <li className="flex items-start gap-2">
                      <ShieldCheck className="h-4 w-4 text-amber-500 shrink-0 mt-0.5" />
                      <span>
                        <strong>Separate tickets and rules:</strong> Because each train is booked separately, cancellation or modification of one ticket does not automatically alter the other ticket. Review Indian Railways cancellation terms for each PNR.
                      </span>
                    </li>
                    <li className="flex items-start gap-2">
                      <CheckCircle2 className="h-4 w-4 text-amber-500 shrink-0 mt-0.5" />
                      <span>
                        <strong>No guaranteed availability:</strong> Quota status is dynamic. A confirmed seat shown during search must still be completed on IRCTC before tickets sell out.
                      </span>
                    </li>
                  </ul>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Visible FAQ Section */}
        <section className="border-b border-border/40 px-4 py-12 sm:px-6 lg:px-8">
          <div className="mx-auto max-w-5xl">
            <h2 className="text-2xl font-bold tracking-tight text-foreground sm:text-3xl mb-2 flex items-center gap-2.5">
              <HelpCircle className="h-6 w-6 text-primary" />
              Frequently Asked Questions
            </h2>
            <p className="text-sm text-muted-foreground mb-8">
              Everything you need to know about planning and booking split train journeys.
            </p>

            <div className="space-y-4">
              {SPLIT_FAQS.map((faq, idx) => (
                <div
                  key={idx}
                  className="rounded-2xl border border-border/60 bg-card/40 p-5 sm:p-6 text-left"
                >
                  <h3 className="font-bold text-foreground text-sm sm:text-base mb-2">
                    {faq.q}
                  </h3>
                  <p className="text-xs sm:text-sm text-muted-foreground leading-relaxed">
                    {faq.a}
                  </p>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* Related tools */}
        <section className="border-b border-border/40 px-4 py-12 sm:px-6 lg:px-8">
          <div className="mx-auto max-w-5xl">
            <h2 className="text-2xl font-bold tracking-tight text-foreground sm:text-3xl mb-3">
              Related tools
            </h2>
            <p className="text-sm text-muted-foreground leading-relaxed">
              Once you have chosen a combination, follow each leg on the day with{" "}
              <Link
                href="/live"
                className="text-primary font-semibold hover:underline"
              >
                live train running status
              </Link>
              , set a destination wake-up alarm for the transfer station using the{" "}
              <Link
                href="/tracker"
                className="text-primary font-semibold hover:underline"
              >
                train tracker
              </Link>
              , check whether an existing booking is likely to clear with{" "}
              <Link
                href="/pnr"
                className="text-primary font-semibold hover:underline"
              >
                PNR status and confirmation prediction
              </Link>
              , review confirmed-seat alternatives through{" "}
              <Link
                href="/ai-waitlist-rescue"
                className="text-primary font-semibold hover:underline"
              >
                AI waitlist rescue
              </Link>
              , compare on-station catering prices against the{" "}
              <Link
                href="/rate-list"
                className="text-primary font-semibold hover:underline"
              >
                IRCTC station rate list
              </Link>
              , or plan segments on the move with the{" "}
              <Link
                href="/app"
                className="text-primary font-semibold hover:underline"
              >
                Trayago Android app
              </Link>
              .
            </p>
          </div>
        </section>

        {/* Regulatory & Non-Affiliation Disclaimer */}
        <section className="px-4 py-10 sm:px-6 lg:px-8 bg-card/40 text-center">
          <div className="mx-auto max-w-4xl text-xs text-muted-foreground leading-relaxed">
            <p className="font-semibold text-foreground mb-1">Regulatory &amp; Non-Affiliation Notice</p>
            <p>
              Trayago is an independent travel intelligence and journey planning platform. Trayago is not affiliated with,
              endorsed by, or operated by IRCTC (Indian Railway Catering and Tourism Corporation) or Indian Railways.
              Ticket booking, payment processing, and seat allocations are completed strictly through official railway reservation platforms.
            </p>
          </div>
        </section>
      </div>
    </>
  );
}
